// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address payable owner;

    function setUp() public { c = new MyContract(); owner = payable(address(this)); }

    function testFuzz_property(address caller, uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        vm.assume(caller != address(0));
        vm.deal(address(c), 1 ether);

        bool ok;
        vm.prank(caller);
        try c.sendTo({receiver: caller, amount: amount}) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            assertTrue(address(c).balance == 1 ether);
        } else {
            assertTrue(address(c).balance <= 1 ether);
        }
    }
}
